#include <memory>
#include <iostream>
using namespace std;

// مینوئل (خطرناک)
int* manualPtr = new int(42);
cout << *manualPtr;
delete manualPtr; // بھول جانے پر میموری لیک!

// سمارٹ (محفوظ)
unique_ptr<int> smartPtr = make_unique<int>(42);
cout << *smartPtr; // ڈیلیٹ کرنے کی ضرورت نہیں!
```
